#pragma once
#include <cstddef>
#include <cstdint>

namespace veyra::pipeline::smaa {
// SMAA precomputed area / search textures (src/pipeline/SmaaLookupTables.cpp,
// generated by scripts/generate-smaa-lookup-tables.py). Rows top to bottom,
// tightly packed: AreaTex R8G8_UNORM, SearchTex R8_UNORM.
inline constexpr uint32_t kAreaTexWidth=160,kAreaTexHeight=560,kAreaTexPitch=kAreaTexWidth*2;
inline constexpr uint32_t kSearchTexWidth=64,kSearchTexHeight=16,kSearchTexPitch=kSearchTexWidth;
inline constexpr size_t kAreaTexBytes=size_t(kAreaTexPitch)*kAreaTexHeight;
inline constexpr size_t kSearchTexBytes=size_t(kSearchTexPitch)*kSearchTexHeight;
extern const uint8_t kAreaTex[kAreaTexBytes];
extern const uint8_t kSearchTex[kSearchTexBytes];
}
